import sympy
from sympy import Matrix

# Top-level setup
# No specific named groups needed for this linear algebra / free abelian group theorem.
# We will use sympy matrices directly.

CONDITION_LABELS = [
    "H_1: n is a positive integer",
    "H_2: G is the free abelian group Z^n",
    "H_3: The determinant of A is non-zero",
    "H_4: H is the subgroup of G generated by the column vectors of A",
    "not Q: The index of H in G is not finite or not equal to the absolute value of the determinant of A"
]

N_HYP = 4
NEG_Q_INDEX = 4

def conditions(witness) -> list[bool]:
    # witness could be a sympy Matrix A, or a tuple (n, A)
    try:
        if isinstance(witness, tuple) and len(witness) == 2:
            n_val, A = witness
        else:
            A = witness
            n_val = A.rows if hasattr(A, 'rows') else 0
            
        if not getattr(A, 'is_Matrix', False):
            return [False, False, False, False, False]
            
        if not A.is_square:
            return [False, False, False, False, False]
            
        h1_ok = bool(isinstance(n_val, int) and n_val > 0 and A.rows == n_val)
    except Exception:
        h1_ok = False

    # H_2 and H_4 are structural definitions in this context.
    # H_2 defines the group G as Z^n.
    # H_4 defines H as the subgroup generated by the columns of A.
    h2_ok = True
    h4_ok = True

    try:
        d = A.det()
        h3_ok = bool(d != 0)
    except Exception:
        h3_ok = False

    try:
        # Check if A is an integer matrix
        # If A is an integer matrix with det(A) != 0, the index is ALWAYS exactly |det(A)|.
        # The dropped hypothesis was that A is an integer matrix.
        # If A is not an integer matrix, the conclusion fails (index is undefined or not |det(A)|).
        is_integer = True
        for v in A:
            if hasattr(v, 'is_integer') and v.is_integer == True:
                continue
            elif isinstance(v, (int, sympy.Integer)):
                continue
            else:
                is_integer = False
                break
                
        if not is_integer:
            neg_q = True
        else:
            d = A.det()
            if d == 0:
                neg_q = True
            else:
                neg_q = False
    except Exception:
        neg_q = False

    return [h1_ok, h2_ok, h3_ok, h4_ok, neg_q]